import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen3Test {













    @Test
    public void testToLocale_SpecialCaseUnderscoreAtFourthIndex() {
        // The logic: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // Example: "en__us" -> language="en", country="", variant="us"
        // Note: The code uses substring(4) which for "en__us" is "us"
        Locale expected = new Locale("en", "", "us");
        assertEquals(expected, LocaleUtils.toLocale("en__us"));
    }








}

